update events set legs = 1, tiebreak = 'diff', ko_target_score = 21, ko_win_by = 1, ko_cap = 21, ko_switch_at = 0, play_clock = true, court_dispatch = 'pool', bracket_preview = true, tv_partner = 'MCXD' where id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCMD');

update events set legs = 1, tiebreak = 'diff', ko_target_score = 21, ko_win_by = 1, ko_cap = 21, ko_switch_at = 0, play_clock = true, court_dispatch = 'pool', bracket_preview = true, tv_partner = 'MCMD' where id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCXD');

update matches m set home_court = c.id
from (values (1, 1), (2, 2), (3, 3), (4, 1), (5, 2), (6, 3), (7, 1), (8, 2), (9, 3), (10, 1), (11, 2), (12, 3), (13, 1), (14, 2), (15, 3), (16, 1), (17, 2), (18, 3), (19, 1), (20, 2), (21, 3), (22, 1), (23, 2), (24, 3), (25, 1), (26, 2), (27, 3), (28, 1), (29, 2), (30, 3), (31, 1), (32, 2), (33, 3), (34, 1), (35, 2), (36, 3), (37, 1), (38, 2), (39, 3), (40, 1), (41, 2), (42, 3), (43, 1), (44, 2), (45, 3), (46, 1), (47, 2), (48, 3)) as v(seq, n)
join courts c on c.number = v.n and c.competition_id = (select id from competitions where code = 'MCMD')
where m.event_id = (select e.id from events e join competitions c on c.id = e.competition_id where c.code = 'MCMD') and m.sequence = v.seq;

update matches m set home_court = c.id
